const body = $input.first().json;
const opps = (body.data && (body.data.opportunities || Object.values(body.data)[0])) || [];
const byStage = {};
for (const o of opps) (byStage[o.stage] = byStage[o.stage] || []).push(o);
const n = (s) => (byStage[s] || []).length;
const names = (s, max = 3) => (byStage[s] || []).slice(0, max).map(o => (o.name || '').replace(/ \((pre-)?seed\)$/i, '')).join(', ');
const weekAgo = Date.now() - 7 * 24 * 3600 * 1000;
const fresh = opps.filter(o => o.createdAt && new Date(o.createdAt).getTime() > weekAgo);
const L = [];
L.push('📋 Pipeline digest');
L.push('');
L.push(`• ${n('NEW')} in New waiting for review`);
L.push(`• ${fresh.length} added this week`);
if (n('REACH_OUT')) L.push(`• ${n('REACH_OUT')} flagged for reach out: ${names('REACH_OUT')}`);
if (n('SEQUENCE_RUNNING')) L.push(`• ${n('SEQUENCE_RUNNING')} sequence running: ${names('SEQUENCE_RUNNING')}`);
if (n('REPLIED')) L.push(`• ${n('REPLIED')} replied and waiting on you: ${names('REPLIED')}`);
if (n('FIRST_MEETING')) L.push(`• ${n('FIRST_MEETING')} first meeting booked: ${names('FIRST_MEETING')}`);
L.push(`• ${n('SHORTLIST')} in Shortlist`);
L.push(`• ${n('OUT_OF_SCOPE')} filed out of scope`);
return [{ json: { digest: L.join('\n') } }];
